const badges=sources=>`<div class="source-badges">${sources.map(id=>sourceMap.get(id)).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label.split(':')[0])} ↗</a>`).join('')}</div>`;
function readLease(){try{return JSON.parse(localStorage.getItem(LEASE_STORE)||'null');}catch{return null;}}
function writeLease(value){try{localStorage.setItem(LEASE_STORE,JSON.stringify(value));return true;}catch{return false;}}
function claimExam(id){const now=Date.now(),current=readLease();if(current?.examId===id&&current.completed)return false;if(current&&!current.completed&&current.owner!==TAB_ID&&current.expiresAt>now)return false;const next={examId:id,owner:TAB_ID,expiresAt:now+LEASE_MS,completed:false};if(!writeLease(next)){memoryLeaseId=id;return true;}memoryLeaseId=null;return readLease()?.owner===TAB_ID;}
function ownsExam(){if(memoryLeaseId===exam?.id)return true;const lease=readLease();return !!exam&&!exam.result&&lease?.examId===exam.id&&lease.owner===TAB_ID&&!lease.completed;}
function renewLease(){if(!exam||exam.result||memoryLeaseId===exam.id)return;const lease=readLease();if(lease?.examId===exam.id&&lease.owner===TAB_ID&&!lease.completed)writeLease({...lease,expiresAt:Date.now()+LEASE_MS});}
function closeLease(id){if(memoryLeaseId===id){memoryLeaseId=null;return;}const lease=readLease();if(lease?.examId===id&&lease.owner===TAB_ID)writeLease({...lease,completed:true,expiresAt:Date.now()+86400000});}
function historyKey(item){return item.id||`legacy:${item.at}:${item.errors}:${item.unanswered}`;}
function mergeState(remote,local){
  const rewards=[...new Set([...remote.rewards,...local.rewards])].slice(-10000);
  const merged={...local,...mergeJourneyProfile(remote,local),xp:Math.max(remote.xp,local.xp,rewards.length*15),sessions:Math.max(remote.sessions,local.sessions),rewards,records:mergeAssessmentRecords(remote.records,local.records)};
  const history=new Map(remote.history.map(item=>[historyKey(item),item]));for(const item of local.history)history.set(historyKey(item),item);merged.history=[...history.values()].sort((a,b)=>a.at-b.at).slice(-30);
  const lease=readLease(),localId=local.savedExam?.id,remoteId=remote.savedExam?.id;
  if(lease?.completed&&(localId===lease.examId||remoteId===lease.examId))merged.savedExam=null;
  else if(lease&&!lease.completed&&lease.owner!==TAB_ID)merged.savedExam=remote.savedExam;
  else merged.savedExam=local.savedExam;
  return merged;
}
function loadProfile(){return readProtectedProfile(localStorage,{legacyKey:STORE,protectedKey:PROTECTED_STORE,merge:mergeState});}
function save(){try{state=mergeState(loadProfile(),state);writeProtectedProfile(localStorage,state,{legacyKey:STORE,protectedKey:PROTECTED_STORE});}catch{if(!storageWarning){storageWarning=true;toast('Din browser kan ikke gemme. Du kan stadig øve i denne session.');}}}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
function sound(correct=true){void experience.play(correct?'correct':'repair');}
function applySettings(){narrator.stop();if(!state.settings.sound)experience.stop();document.body.classList.toggle('calm',!state.settings.humor);document.body.classList.toggle('no-motion',!state.settings.motion||reduceMotion.matches);$('humor-toggle').setAttribute('aria-pressed',String(state.settings.humor));$('humor-toggle').querySelector('b').textContent=state.settings.humor?'ON':'OFF';$('sound-toggle').setAttribute('aria-pressed',String(state.settings.sound));$('sound-toggle').title=state.settings.sound?'Små lyde er tændt':'Små lyde er slukket';world?.setMotion(state.settings.motion&&!reduceMotion.matches);judgeGame?.setHumor(state.settings.humor);judgeGame?.setMotion(state.settings.motion&&!reduceMotion.matches);}
function makeWorld(canvas,options={}){const q=canvas.id==='question-scene'?(location.hash==='#exam'&&exam?exam.questions[exam.index]:currentQuestion()):null;world?.dispose();world=createNightWorld(canvas,{...options,question:q||options.question,motion:state.settings.motion&&!reduceMotion.matches});world?.setQuestion?.(q);if(!world){canvas.hidden=true;const fallback=document.createElement('div');fallback.className='webgl-fallback';canvas.parentElement.append(fallback);}}
function teardown(){heroDispose?.();heroDispose=null;orderDispose?.();orderDispose=null;chatDispose?.();chatDispose=null;dayNightDispose?.();dayNightDispose=null;startDispose?.();startDispose=null;turnPlayer?.dispose();turnPlayer=null;journeyRoad?.dispose();journeyRoad=null;journeyPlayer?.dispose();journeyPlayer=null;narrator.stop();questionVisual?.dispose();questionVisual=null;world?.dispose();world=null;judgeGame?.dispose();judgeGame=null;window.speechSynthesis?.cancel();}
function setNav(route){const active=['chapter','lesson','learn','garage','garage-zone','theory','journey'].includes(route)?'home':['missions','mission','result','review','drive','judge','trafiklab','order'].includes(route)?'practice':route==='exam-result'?'exam':route;for(const id of ['desktop-nav','mobile-nav'])$(id).innerHTML=nav.map(([r,label,i])=>`<a href="#${r}" data-tab="${r}" class="${id==='desktop-nav'?'nav-item':''} ${active===r?'active':''}" ${active===r?'aria-current="page"':''} aria-label="${label}"><span class="nav-tile">${duo(i)}</span><span class="nav-label">${label}</span>${id==='desktop-nav'&&r==='practice'&&dueCount()?`<span class="nav-count">${dueCount()}</span>`:''}</a>`).join('');const prof=document.querySelector('.nav-item--profile');if(prof){prof.innerHTML=`<span class="nav-tile">${duo('profile')}</span><span class="nav-label">Din profil</span>`;prof.classList.toggle('active',route==='profil');}}
function footer(){return `<details class="experience-status"><summary>Kilder & faglig status</summary><p class="fine-print">TeoriBoost er et selvstændigt øvekoncept. ${QUESTIONS.length} originale øvescenarier og ${uniqueSections} korte regelkort med myndighedskilder. Garagen uddyber ${garageSummary.topics} bilområder med delmål og opgaver til køretimen. Hele appen er endnu ikke en komplet undervisningsbog. <button class="text-link" data-action="sources">Se faglig status ↗</button></p></details>`;}
function heading(kicker,title,extra=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1></div>${extra}</div>`;}
function route(){teardown();const bits=location.hash.slice(1).split(':');let r=bits[0]||'home';const arg=bits[1]||'';if(r==='home'&&!arg&&isFirstRun()){history.replaceState(null,'','#start');r='start';}document.body.classList.toggle('start-mode',r==='start');document.body.classList.toggle('chat-mode',r==='chat');syncFab(r);document.body.classList.toggle('focus-mode',['journey','mission','review','learn','lesson','result'].includes(r)||(r==='order'&&!!arg)||r==='judge'||r==='trafiklab'||(r==='exam'&&!!exam&&!exam.result));if(r==='exam'&&exam?.result)exam=null;if(r==='exam-result'&&!exam?.result){for(const item of [...state.history].reverse()){const recovered=restoreExamResult(item,QUESTIONS,{requireSignatures:true});if(recovered){exam=recovered;break;}}}if(r==='exam-result'&&exam&&!exam.result){history.replaceState(null,'','#exam');r='exam';}setNav(r);document.body.classList.toggle('journey-surface',['home','progress','journey','learn'].includes(r));document.body.classList.toggle('journey-focus',['journey','learn'].includes(r));document.body.classList.toggle('exam-active',r==='exam'&&!!exam);if(r==='exam'&&exam)experience.stop();let content;
  switch(r){case 'order':content=arg?renderOrder(arg):renderOrderList();break;case 'chat':content=renderChat({history:loadChat()});break;case 'start':content=renderStart(Math.min(4,Math.max(0,Number(arg)||0)),{intro:loadIntro(),counts:{questions:QUESTIONS.length,lessons:uniqueSections},plan:startPlan()});break;case 'home':content=learnView(arg);break;case 'practice':content=practiceView();break;case 'profil':content=profileView();break;case 'trafiklab':content='<div id="turn-player-host"></div>'+footer();break;case 'journey':content='<div id="journey-player-host"></div>'+footer();break;case 'judge':content='<div id='+String.fromCharCode(34)+'judge-host'+String.fromCharCode(34)+'>'+renderJudge()+'</div>';break;case 'pitstop':content=home();break;case 'missions':content=missions();break;case 'mission':if(!session||arg)startMission(arg);content=missionView();break;case 'review':startReview();content=missionView();break;case 'theory':content=topicsView();break;case 'garage':content='<div id="garage-host">'+renderGarage(arg)+'</div>'+footer();break;case 'garage-zone':content='<div id="garage-host">'+renderGarage('',arg)+'</div>'+footer();break;case 'chapter':content=chapterView(arg);break;case 'lesson':content=renderLesson(sectionMap.get(arg),LESSONS[arg])+footer();break;case 'learn':content='<div id="journey-player-host"></div>'+footer();break;case 'exam':content=exam?examView():examIntro();break;case 'progress':content=journeyProgressPage(arg);break;case 'minbil':content=myCarView()+footer();break;case 'result':content=missionResult();break;case 'exam-result':content=examResult();break;case 'drive':content=driveView();break;default:content=renderJourneyHome(journeyViewModel())+footer();}
  $('view').innerHTML=content;applySettings();if(r==='exam-result'&&examSting){const cue=examSting;examSting='';setTimeout(()=>void experience.play(cue),350);}journeyRoad=(roads=>({dispose(){roads.forEach(r=>r.dispose());}}))([mountJourneyRoad($('view')),mountLearnRoad($('view'))]);bindPage(r,arg);afterRender(r);const focusTarget=r==='exam'?document.querySelector('.question-panel h2'):r==='exam-result'?document.querySelector('.result-hero h1'):$('main');if(focusTarget){focusTarget.setAttribute('tabindex','-1');focusTarget.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});document.title=(r==='home'?'TeoriBoost — din hjerne. Dit kørekort.':'TeoriBoost — '+(nav.find(n=>n[0]===r)?.[1]||(r==='minbil'?'Min bil':'Træning')));
}
function refreshJourneyAppearance(){if(turnPlayer){turnPlayer.refresh();return;}if(['home','progress','journey','learn'].includes(location.hash.slice(1).split(':')[0]||'home')){const offset=window.scrollY;if(journeyPlayer)journeyPlayer.refresh();else route();window.scrollTo({top:offset,behavior:'instant'});}}
function journeyViewModel(activeUnitId=''){
  const input={chapters:CHAPTERS,lessons:LESSONS,questions:QUESTIONS,journey:state.journey,records:state.records,now:Date.now()};
  return {units:getRouteUnits(input),daily:getDailySummary(state.journey,input.now),recommendations:getJourneyRecommendations(input),humor:state.settings.humor,activeUnitId:activeUnitId||undefined};
}
function journeyProgressPage(arg){
  return renderTurnEntry(state.turnLab)+renderJourneyProgress(journeyViewModel(arg))+'<div class="section-head"><h2>Dine vurderinger og prøver.</h2></div><p class="muted">'+practiced()+(practiced()===1?' regel vurderet · ':' regler vurderet · ')+mastered()+' gentaget over mindst to dage. Din tidligere fremgang er bevaret.</p>'+(state.history.length?'<div class="result-list">'+[...state.history].reverse().map(item=>'<div class="result-row"><span class="result-indicator '+(item.errors>5?'wrong':'')+'">'+item.errors+'</span><div><h3>'+item.errors+' app-fejl / 25</h3><p>'+new Date(item.at).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})+' · '+item.unanswered+' ubesvarede</p></div></div>').join('')+'</div>':'')+footer();
}
function finishJourney(evidence,activeSession){
  const result=completeLesson(state.journey,evidence,Date.now());
  if(!result.accepted){if(!result.duplicate)toast('Lektionen mangler et trin før den kan gemmes.');return;}
  state.journey=result.state;
  const record=state.records[evidence.sectionId];
  if(record && (activeSession.recall.selfCheck==='needs-review' || evidence.apply.hadWrong || evidence.checkpoint.hadWrong))record.due=Math.min(record.due,Date.now()+20*60000);
  save();
}
