var startDispose; // no initialiser: the first route() may already have set it
function isFirstRun(){return !loadIntro().done&&!(state.journey?.events?.length)&&!(state.history?.length);}
// The start page's glow-up machine as Rive (the Hero artboard, one vehicle per file, swapped when it has driven off).
// The CSS machine runs instead when motion is off or Rive fails. Returns a dispose function.
function mountHero(gu,opts){
  if(document.body.classList.contains('no-motion')||reduceMotion.matches)return mountGlowUp(gu,opts);
  const stage=gu.querySelector('.gu-stage'),bases=(gu.dataset.glowup||'scooter').split(','),loop=gu.dataset.loop==='1';
  const from=gu.querySelector('.gu-from'),to=gu.querySelector('.gu-to');
  let i=0,timers=[],stop=null,dead=false;
  const clear=()=>{timers.forEach(clearTimeout);timers=[];};
  const show=b=>{gu.dataset.active=b;if(from){from.textContent=DREAMS[b].from;to.textContent=DREAMS[b].to;}gu.setAttribute('aria-label',`${DREAMS[b].from} bliver til ${DREAMS[b].to}, del for del`);riveSwap(stage,'hero:'+b);};
  const onOn=()=>{if(dead)return;clear();const b=bases[i],next=bases[(i+1)%bases.length];if(bases.length>1)rivePreload('hero:'+next);
    timers=dreamCues(b).map(([ms,cue])=>setTimeout(()=>opts.sound?.(cue),ms));
    timers.push(setTimeout(()=>{if(!loop&&i===bases.length-1){opts.onDone?.();return;}i=(i+1)%bases.length;show(bases[i]);},7250));}; // 7250: the Hero show's length (tools/rive/build-glowup.mjs)
  const onOff=()=>{if(dead||stop)return;clear();stage.removeEventListener('rive-on',onOn);stage.removeAttribute('data-rive');stage.removeAttribute('data-rive-on');stop=mountGlowUp(gu,opts);};
  stage.addEventListener('rive-on',onOn);stage.addEventListener('rive-off',onOff,{once:true});
  gu.dataset.active=bases[0];stage.dataset.rive='hero:'+bases[0];
  return()=>{dead=true;clear();stage.removeEventListener('rive-on',onOn);stop?.();};
}
function startPlan(){const vm=journeyViewModel('');const next=vm.recommendations?.recommended||vm.recommendations?.next||vm.units.flatMap(u=>u.nodes||[])[0];return {firstTitle:next?.title||'Dit første regelkort',firstHref:next?'#journey:'+next.sectionId:'#home'};}
function mountStart(){
  const view=$('view');const step=Number(location.hash.split(':')[1])||0;
  typeBubbles(view);countUps(view);
  const gu=view.querySelector('.gu');
  if(gu){const run=()=>{startDispose?.();const t0=Date.now();startDispose=mountHero(gu,{sound:step===3?cue=>{if(Date.now()-t0<15000)void experience.play(cue);}:()=>{},onDone:()=>{const b=view.querySelector('[data-start-replay]');if(b)b.hidden=false;}});};run();mountStart.replay=run;}
  if(step===4){setTimeout(()=>{confetti({origin:{x:.5,y:.3}});void experience.play('milestone');},900);}
}
document.addEventListener('click',e=>{
  const pick=e.target.closest('[data-start-pick]');
  if(pick){const name=pick.dataset.startPick,value=pick.dataset.value;saveIntro(name==='when'?{when:value,whenAt:Date.now()}:{[name]:name==='goal'?Number(value):value});
    if(name==='goal'){state.journey=setDailyGoal(state.journey,Number(value));save();}
    for(const o of pick.parentElement.querySelectorAll('[data-start-pick]')){const on=o===pick;o.classList.toggle('is-on',on);o.setAttribute('aria-checked',String(on));}
    void experience.play('select');return;}
  if(e.target.closest('[data-start-skip]')){saveIntro({done:true});return;}
  if(e.target.closest('[data-start-go],[data-start-next]')){void experience.play('step');return;}
  if(e.target.closest('[data-start-replay]')){e.target.closest('[data-start-replay]').hidden=true;mountStart.replay?.();return;}
  const claim=e.target.closest('[data-start-claim]');
  if(claim){e.preventDefault();void experience.play('buy');confetti({origin:{x:.5,y:.4},count:90});setTimeout(()=>{location.hash='start:4';},650);return;}
  if(e.target.closest('[data-start-finish]')){saveIntro({done:true});void experience.play('step');}
});

// Min bil: watch the dream build of your own vehicle, part by part
// The Rive show (glowup-<base>.riv) plays when it can; the CSS glow-up runs if Rive is off or fails.
// sound cues on the Rive show's timeline (tools/rive/build-glowup.mjs): cough, scan, pop, landing, five parts, neon
function dreamCues(base){return [[1150,'rev-'+base],[2080,'paint'],[3420,'booster'],[3830,'lower'],...[0,1,2,3,4].map(i=>[4200+i*283,'part']),[5620,'neon']];} // a declaration: the first route() runs before this line

