function learnView(arg){const vm=journeyViewModel(arg);const units=vm.units||[];const next=vm.recommendations?.recommended||vm.recommendations?.next;const idx=Math.max(0,units.findIndex(u=>u.id===(arg||units.find(x=>(x.nodes||[]).some(n=>n.id===next?.id))?.id)));return renderLearn({vm:{...vm,activeUnitId:arg||units[idx]?.id},intro:loadIntro(),due:dueCount(),unitIndex:idx,ready:readiness()});}
function weakRules(){const titles=new Map(CHAPTERS.flatMap(c=>c.sections.map(x=>[x.id,x.title])));return Object.entries(state.records).filter(([,r])=>r.lastAssessment==='complete'&&!r.lastCorrect||r.due<=Date.now()).map(([id])=>({id,title:titles.get(id)||id}));}
function practiceView(){const MISSION_LOOK={stop:['stop','#FFE3E6'],'sving-cykel':['bike','#E3F4FF'],ubetinget:['yield','#FFF5CC']};return renderPractice({weak:weakRules(),due:dueCount(),missions:featured.map(f=>({section:f.section,title:f.name,icon:MISSION_LOOK[f.section]?.[0]||'car',tint:MISSION_LOOK[f.section]?.[1]||'#F3F5F7'}))});}
function topicsView(){const vm=journeyViewModel('');return renderTopics({units:vm.units||[],chapters:CHAPTERS,activeUnitId:(vm.units||[]).find(u=>(u.nodes||[]).some(n=>n.id===(vm.recommendations?.recommended||vm.recommendations?.next)?.id))?.id});}
function topicsList(){const d=document.createElement('div');d.innerHTML=topicsView();return d.querySelector('#theory-results').innerHTML;}
function profileView(){const vm=journeyViewModel('');const nodes=(vm.units||[]).flatMap(u=>u.nodes||[]);
  const strengths=CHAPTERS.map(c=>{const rs=c.sections.map(x=>state.records[x.id]).filter(r=>r&&(r.assessments>0||r.lastAssessment==='complete'));return rs.length?{title:c.title,score:rs.filter(r=>r.lastCorrect).length/rs.length,n:rs.length}:null;}).filter(Boolean).sort((a,b)=>b.score-a.score);
  const pick=strengths.length>4?[...strengths.slice(0,2),...strengths.slice(-2)]:strengths;
  return renderProfile({daily:vm.daily,lessonsDone:nodes.filter(n=>n.lessonComplete).length,lessonsTotal:nodes.length,strengths:pick,intro:loadIntro(),settings:state.settings,examDays:examCountdown(loadIntro()),ready:readiness(),account:account?.status()});}
