/** Readiness: the share of rule cards whose latest answer was right. Honest and explainable. */
function readiness(){const total=uniqueSections;const ok=Object.values(state.records).filter(r=>r.lastCorrect&&(r.assessments>0||r.lastAssessment==='complete')).length;const passes=state.history.slice(-3).filter(h=>h.errors<=5).length;return {pct:Math.min(100,Math.round(ok/total*100)),ok,total,passes};}

