// The logo intro, once per visit: dark screen, the Rive logo (the static mark until it runs), the name fades in.
// Any tap or key skips it; nothing shows when motion is off.
(function logoIntro(){
  if(document.body.classList.contains('no-motion')||reduceMotion.matches)return;
  try{if(sessionStorage.getItem('teoriboost.logoIntro'))return;sessionStorage.setItem('teoriboost.logoIntro','1');}catch{return;}
  const el=document.createElement('div');el.className='logo-intro';el.setAttribute('aria-hidden','true');
  el.innerHTML=`<div class="logo-intro__mark" data-rive="logo"><span class="brand-mark"><svg viewBox="0 0 64 64" focusable="false"><path d="M9.8 46.8h6.8l16-29.6h-6.8zM20.6 46.8h6.8l16-29.6h-6.8zM31.4 46.8h6.8l16-29.6h-6.8z"/></svg></span></div><b class="logo-intro__name">TeoriBoost</b>`;
  document.body.append(el);
  let gone=false;const done=()=>{if(gone)return;gone=true;el.classList.add('is-out');setTimeout(()=>el.remove(),400);};
  el.addEventListener('rive-on',()=>{el.classList.add('is-on');setTimeout(done,1900);},{once:true});
  el.addEventListener('rive-off',done,{once:true});
  setTimeout(()=>{if(!el.classList.contains('is-on'))done();},1100); // Rive not there yet: the static mark was enough
  el.addEventListener('pointerdown',done);addEventListener('keydown',done,{once:true});
})();
// "Kom i gang" on the intro: the Rive button lights up while pointed at or focused, and drives off when pressed
const ctaOf=t=>t?.closest?.('.cta-rive[data-rive-on="on"]');
for(const [type,on] of [['pointerover',true],['pointerout',false],['focusin',true],['focusout',false]])
  document.addEventListener(type,e=>{const w=ctaOf(e.target);if(w&&(on||!w.contains(e.relatedTarget)))riveSet(w,'hover',on);});
document.addEventListener('click',e=>{const w=ctaOf(e.target),a=w&&e.target.closest('[data-start-go]');if(!a)return;e.preventDefault();if(a.classList.contains('is-launch'))return;
  riveFire(w,'press');a.classList.add('is-launch');void experience.play('rev-racecar');setTimeout(()=>{location.hash=a.hash;},620);},true);
